SELECT ws.ws_order_number, ca.ca_state, ws.ws_quantity * ws.ws_list_price AS total_list_price, CASE WHEN ws.ws_net_profit > 528.00 THEN 'Profitable' ELSE 'Not Profitable' END AS profit_category, ws.ws_ext_sales_price - ws.ws_ext_discount_amt AS net_sales, ws.ws_wholesale_cost * ws.ws_quantity AS total_wholesale_cost, ws.ws_ext_sales_price / NULLIF(ws.ws_quantity, 0) AS avg_price_per_item, CASE WHEN ca.ca_gmt_offset > -8.00 THEN 'East' ELSE 'West' END AS region FROM web_sales ws JOIN customer_address ca ON ws.ws_bill_addr_sk = ca.ca_address_sk WHERE ws.ws_sold_date_sk = 2452062
